CREATE TABLE IF NOT EXISTS urgent_pass_usage (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE, student_id UUID NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE, subject_id UUID NOT NULL REFERENCES subjects(id) ON DELETE CASCADE, week_start DATE NOT NULL, used_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE (student_id, subject_id, week_start));
